method split_words(txt: string) returns (result: seq<string>)
    requires txt != null
    ensures (
        // If there are whitespace characters in the input string
        (exists i: int :: 0 <= i < txt.Length && (txt[i] == ' ' || txt[i] == '\t' || txt[i] == '\n')) ==> 
            result == txt.Split(' ')
        ||
        // If there are no whitespace characters but there are commas
        (forall i: int :: 0 <= i < txt.Length && (txt[i] != ' ' && txt[i] != '\t' && txt[i] != '\n') 
            ==> (exists j: int :: 0 <= j < txt.Length && txt[j] == ',')) ==> 
            result == txt.Split(',')
        ||
        // If there are no whitespace and no commas, return the count of lower-case letters with odd order
        (forall i: int :: 0 <= i < txt.Length && (txt[i] != ' ' && txt[i] != ',' && txt[i] != '\t' && txt[i] != '\n') 
            ==> (txt[i] >= 'a' && txt[i] <= 'z' && (ord(txt[i]) % 2 == 1))) ==> 
            result == CountLowerCaseOddOrder(txt)
        )
    )
{
    // The helper function to count the lower-case letters with odd order in the alphabet
    function CountLowerCaseOddOrder(txt: string): int
        requires txt != null
        ensures 0 <= CountLowerCaseOddOrder(txt) <= txt.Length
    {
        var count := 0;
        var i := 0;
        while i < txt.Length
            invariant 0 <= i <= txt.Length
            invariant count >= 0
        {
            if (txt[i] >= 'a' && txt[i] <= 'z' && (ord(txt[i]) % 2 == 1)) {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }
}

